        unsigned int count = (flags & CurrentInsertCount) >> 5;
        unsigned int start = entry->data.currentInsertIndex;
        const GlyphID *glyphs = &insertionAction[start];
        if (unlikely (!c->sanitizer.check_array (glyphs, count))) return false;

